<template>
  <business-page title="推荐搜索" description="调用 Tavily 获取真实推荐结果，并生成 AI 摘要或加入路书点位。">
    <template #actions><el-button type="primary" icon="Search" @click="openSearch">发起推荐搜索</el-button></template>
    <section class="business-panel search-panel"><el-form :inline="true" :model="query"><el-form-item label="路书"><routebook-select v-model="query.routebookId" class="routebook-filter" /></el-form-item><el-form-item label="偏好编码"><el-input v-model="query.prefCode" clearable /></el-form-item><el-form-item label="推荐标题"><el-input v-model="query.title" clearable @keyup.enter="search" /></el-form-item><el-form-item><el-button icon="Search" @click="search">查询</el-button><el-button icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form></section>
    <section class="business-panel table-panel">
      <page-state v-if="loading" type="loading" description="正在读取推荐结果" /><page-state v-else-if="loadError" type="error" description="推荐结果加载失败，请检查接口后重试。" action-text="重新加载" @action="loadData" /><page-state v-else-if="rows.length === 0" description="当前没有推荐结果，可发起一次真实搜索。" />
      <template v-else><el-table :data="rows" stripe><el-table-column label="推荐内容" min-width="280"><template #default="scope"><div class="recommend-title"><a v-if="scope.row.sourceUrl" :href="scope.row.sourceUrl" target="_blank" rel="noopener noreferrer">{{ scope.row.title || '未命名推荐' }}</a><strong v-else>{{ scope.row.title || '未命名推荐' }}</strong><small>{{ scope.row.sourceDomain || '来源未知' }} · {{ scope.row.prefCode || '未分类' }}</small></div></template></el-table-column><el-table-column label="最终评分" prop="finalScore" width="100" /><el-table-column label="AI 摘要" prop="aiSummary" min-width="260" show-overflow-tooltip /><el-table-column label="创建时间" prop="createTime" min-width="170" /><el-table-column label="操作" width="190" fixed="right"><template #default="scope"><el-button link type="primary" :loading="aiId === scope.row.id" @click="generateAi(scope.row)">生成 AI 摘要</el-button><el-button link type="primary" @click="openAddPoint(scope.row)">加入路书</el-button></template></el-table-column></el-table><pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="loadData" /></template>
    </section>
    <el-dialog v-model="searchOpen" title="发起推荐搜索" width="640px" append-to-body :close-on-click-modal="false" :before-close="beforeClose"><el-form ref="searchFormRef" :model="searchForm" :rules="searchRules" label-width="104px"><el-form-item label="搜索词" prop="queryText"><el-input v-model="searchForm.queryText" placeholder="例如：川西沿途适合摩旅的观景台" /></el-form-item><div class="form-grid"><el-form-item label="路书"><routebook-select v-model="searchForm.routebookId" /></el-form-item><el-form-item label="关联点位 ID"><el-input-number v-model="searchForm.pointId" :min="1" /></el-form-item></div><div class="form-grid"><el-form-item label="偏好编码"><el-input v-model="searchForm.prefCode" /></el-form-item><el-form-item label="搜索深度"><el-select v-model="searchForm.searchDepth"><el-option v-for="item in trip_tavily_search_depth" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item></div><el-form-item label="包含域名"><el-input v-model="includeDomainsText" placeholder="多个域名用逗号分隔" /></el-form-item><el-form-item label="排除域名"><el-input v-model="excludeDomainsText" placeholder="多个域名用逗号分隔" /></el-form-item><el-form-item label="结果数量"><el-input-number v-model="searchForm.maxResults" :min="1" :max="20" /></el-form-item></el-form><template #footer><el-button :disabled="submitting" @click="searchOpen = false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitSearch">开始搜索</el-button></template></el-dialog>
    <el-dialog v-model="pointOpen" title="将推荐加入路书" width="620px" append-to-body :close-on-click-modal="false" :before-close="beforeClose"><el-form ref="pointFormRef" :model="pointForm" :rules="pointRules" label-width="104px"><el-form-item label="点位名称" prop="pointName"><el-input v-model="pointForm.pointName" /></el-form-item><div class="form-grid"><el-form-item label="点位类型"><el-select v-model="pointForm.pointType" clearable placeholder="请选择点位类型"><el-option v-for="item in trip_point_type" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="停留分钟"><el-input-number v-model="pointForm.stayMinutes" :min="0" /></el-form-item></div><div class="form-grid"><el-form-item label="经度"><el-input-number v-model="pointForm.lng" :precision="6" /></el-form-item><el-form-item label="纬度"><el-input-number v-model="pointForm.lat" :precision="6" /></el-form-item></div><el-form-item label="详细地址"><el-input v-model="pointForm.address" /></el-form-item><el-form-item label="备注"><el-input v-model="pointForm.remark" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button :disabled="submitting" @click="pointOpen = false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitPoint">加入路书</el-button></template></el-dialog>
  </business-page>
</template>

<script setup lang="ts" name="TripRecommend">
import { ElMessage } from 'element-plus'
import BusinessPage from '@/components/BusinessPage/index.vue'; import PageState from '@/components/BusinessPage/PageState.vue'
import RoutebookSelect from '@/components/RoutebookSelect/index.vue'
import { addRecommendationToRoutebook, generateRecommendationAi, listRecommendations, searchRecommendations } from '@/api/trip/recommend'
import type { TripRecommend, TripRecommendAddPointRequest, TripRecommendQuery, TripRecommendSearchRequest } from '@/types/api/trip/recommend'
const { trip_tavily_search_depth, trip_point_type } = useDict('trip_tavily_search_depth', 'trip_point_type')
const query = reactive<TripRecommendQuery>({ pageNum: 1, pageSize: 10 }); const rows = ref<TripRecommend[]>([]); const total = ref(0); const loading = ref(false); const loadError = ref(false); const aiId = ref<number>()
const searchOpen = ref(false); const pointOpen = ref(false); const submitting = ref(false); const searchFormRef = ref<any>(); const pointFormRef = ref<any>(); const searchForm = ref<TripRecommendSearchRequest>({ queryText: '', searchDepth: 'basic', maxResults: 5 }); const includeDomainsText = ref(''); const excludeDomainsText = ref(''); const pointForm = ref<TripRecommendAddPointRequest>({}); const selectedId = ref<number>()
const searchRules: Record<string, any[]> = { queryText: [{ required: true, message: '请输入搜索词', trigger: 'blur' }] }; const pointRules: Record<string, any[]> = { pointName: [{ required: true, message: '请输入点位名称', trigger: 'blur' }] }
async function loadData(): Promise<void> { loading.value = true; loadError.value = false; try { const response = await listRecommendations(query); rows.value = response.rows || []; total.value = response.total || 0 } catch (error) { loadError.value = true; console.warn('推荐结果加载失败，请检查推荐列表接口。', error) } finally { loading.value = false } }
function search(): void { query.pageNum = 1; loadData() } function reset(): void { query.routebookId = undefined; query.prefCode = undefined; query.title = undefined; search() }
function openSearch(): void { searchForm.value = { routebookId: query.routebookId, prefCode: query.prefCode, queryText: '', searchDepth: 'basic', maxResults: 5 }; includeDomainsText.value = ''; excludeDomainsText.value = ''; searchOpen.value = true; nextTick(() => searchFormRef.value?.clearValidate()) }
async function submitSearch(): Promise<void> { await searchFormRef.value?.validate(); submitting.value = true; try { const split = (value: string) => value.split(',').map(item => item.trim()).filter(Boolean); await searchRecommendations({ ...searchForm.value, includeDomains: split(includeDomainsText.value), excludeDomains: split(excludeDomainsText.value) }); ElMessage.success('搜索完成，推荐结果已保存'); searchOpen.value = false; query.routebookId = searchForm.value.routebookId; await loadData() } catch (error) { console.warn('推荐搜索失败，请检查搜索条件和第三方服务日志。', error) } finally { submitting.value = false } }
async function generateAi(row: TripRecommend): Promise<void> { aiId.value = row.id; try { await generateRecommendationAi(Number(row.id)); ElMessage.success('AI 摘要生成完成'); await loadData() } catch (error) { console.warn('AI 摘要生成失败，请查看第三方调用日志。', error) } finally { aiId.value = undefined } }
function openAddPoint(row: TripRecommend): void { selectedId.value = row.id; pointForm.value = { pointName: row.title, remark: row.recommendReason || row.aiSummary, checkinRadiusM: 200 }; pointOpen.value = true; nextTick(() => pointFormRef.value?.clearValidate()) }
async function submitPoint(): Promise<void> { await pointFormRef.value?.validate(); submitting.value = true; try { await addRecommendationToRoutebook(Number(selectedId.value), pointForm.value); ElMessage.success('已加入路书点位'); pointOpen.value = false } catch (error) { console.warn('推荐结果加入路书失败，请检查路书和点位参数。', error) } finally { submitting.value = false } }
function beforeClose(done: () => void): void { if (!submitting.value) done() } onMounted(loadData)
</script>

<style scoped lang="scss">
.business-panel{border:1px solid var(--roadbook-border);border-radius:var(--roadbook-radius);background:var(--roadbook-panel-bg);box-shadow:var(--roadbook-shadow)}.search-panel{padding:16px 20px 0;margin-bottom:16px}.routebook-filter{width:280px!important}.table-panel{min-height:340px;padding:16px}.recommend-title a,.recommend-title strong{display:block;color:var(--roadbook-text-primary);font-weight:650}.recommend-title small{display:block;margin-top:6px;color:var(--roadbook-text-secondary)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
</style>
